window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-58931bcfaa1a5ada"]={"versions": [{"id": "FIG-58931bcfaa1a5ada", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablauf- und Synchronisationsdiagramm im Kontext des AUTOSAR OS Schedule Table Managements. Das Diagramm illustriert das Verhalten bei der dynamischen Anpassung von Ablaufzeitpunkten (Expiry Points) einer synchronisierten Schedule Table zur Synchronisation an eine globale Zeitbasis. Dargestellt werden drei Szenarien entlang der Zeitachse: der reguläre Ablauf („Expected Delays“), die maximale Verzögerung („Maximum Retardation“) sowie das maximale Vorziehen („Maximum Advance“).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei aufeinanderfolgende Ablaufpunkte (Expiry Points) einer Schedule Table:</p>\n<ul class=\"fig-list\"><li><code>Expiry Point Current</code>: Konfiguriert mit <code>Offset 10 ticks</code>, <code>Task Activations</code>, <code>Event Settings</code>, <code>MaxRetard</code> und <code>MaxAdvance</code>.\n</li><li><code>Expiry Point Next</code>: Konfiguriert mit <code>Offset 24 ticks</code>, <code>Task Activations</code>, <code>Event Settings</code>, <code>MaxRetard 7 ticks</code> und <code>MaxAdvance 2 ticks</code>.\n</li><li><code>Expiry Point NextNext</code>: Konfiguriert mit <code>Offset 42 ticks</code>, <code>Task Activations</code>, <code>Event Settings</code>, <code>MaxRetard</code> und <code>MaxAdvance</code>.\n</li><li>Zeitachsen-Intervalle (Delays) zwischen den Punkten: Basiskonfiguration <code>Delay = 14 ticks</code> (Differenz 24 - 10) und <code>Delay = 18 ticks</code> (Differenz 42 - 24).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Szenario „Expected Delays“: Die Expiry Points feuern gemäß ihren Nominal-Offsets mit nominellen Abständen von 14 Ticks zwischen Current und Next sowie 18 Ticks zwischen Next und NextNext.\n</li><li>Szenario „Maximum Retardation“: Der Ablaufpunkt <code>Next</code> wird um seinen maximalen Verzögerungswert (<code>MaxRetard = 7 ticks</code>) nach hinten verschoben. Die Verzögerung zwischen Current und Next verlängert sich auf <code>Delay = 14 + 7 = 21 ticks</code>. Der nachfolgende Abstand zwischen Next und NextNext bleibt nominal bei <code>Delay = 18 ticks</code>, sodass sich der absolute Zeitpunkt von NextNext ebenfalls verschiebt.\n</li><li>Szenario „Maximum Advance“: Der Ablaufpunkt <code>Next</code> wird um seinen maximalen Vorziehwert (<code>MaxAdvance = 2 ticks</code>) verkürzt. Die Verzögerung zwischen Current und Next verkürzt sich auf <code>Delay = 14 - 2 = 12 ticks</code> (im Schaubild als Korrektur/Anpassung <code>Delay = 14 +/- 2 = 16 / 12 ticks</code> adressiert). Der anschließende Abstand zu NextNext bleibt mit <code>Delay = 18 ticks</code> unverändert.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht die Randbedingungen für das OS-Modul bei der Synchronisation synchronisierbarer Schedule Tables (AUTOSAR OS SWS). Die Werte <code>OsScheduleTableSyncType</code>, <code>OsScheduleTableMaxRetard</code> und <code>OsScheduleTableMaxAdvance</code> begrenzen den Betrag, um den das Betriebssystem den nächsten Expiry Point verzögern oder vorziehen darf, um Taktabweichungen zur Synchronisationsquelle auszugleichen, ohne die Minimalabstände oder Reihenfolgen von Task-Aktivierungen und Event-Settings zu verletzen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-dd6fe293799ef612", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablauf- und Synchronisationsdiagramm im Kontext des AUTOSAR OS Schedule Table Managements. Das Diagramm illustriert das Verhalten bei der dynamischen Anpassung von Ablaufzeitpunkten (Expiry Points) einer synchronisierten Schedule Table zur Synchronisation an eine globale Zeitbasis. Dargestellt werden drei Szenarien entlang der Zeitachse: der reguläre Ablauf („Expected Delays“), die maximale Verzögerung („Maximum Retardation“) sowie das maximale Vorziehen („Maximum Advance“).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei aufeinanderfolgende Ablaufpunkte (Expiry Points) einer Schedule Table:</p>\n<ul class=\"fig-list\"><li><code>Expiry Point Current</code>: Konfiguriert mit <code>Offset 10 ticks</code>, <code>Task Activations</code>, <code>Event Settings</code>, <code>MaxRetard</code> und <code>MaxAdvance</code>.\n</li><li><code>Expiry Point Next</code>: Konfiguriert mit <code>Offset 24 ticks</code>, <code>Task Activations</code>, <code>Event Settings</code>, <code>MaxRetard 7 ticks</code> und <code>MaxAdvance 2 ticks</code>.\n</li><li><code>Expiry Point NextNext</code>: Konfiguriert mit <code>Offset 42 ticks</code>, <code>Task Activations</code>, <code>Event Settings</code>, <code>MaxRetard</code> und <code>MaxAdvance</code>.\n</li><li>Zeitachsen-Intervalle (Delays) zwischen den Punkten: Basiskonfiguration <code>Delay = 14 ticks</code> (Differenz 24 - 10) und <code>Delay = 18 ticks</code> (Differenz 42 - 24).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Szenario „Expected Delays“: Die Expiry Points feuern gemäß ihren Nominal-Offsets mit nominellen Abständen von 14 Ticks zwischen Current und Next sowie 18 Ticks zwischen Next und NextNext.\n</li><li>Szenario „Maximum Retardation“: Der Ablaufpunkt <code>Next</code> wird um seinen maximalen Verzögerungswert (<code>MaxRetard = 7 ticks</code>) nach hinten verschoben. Die Verzögerung zwischen Current und Next verlängert sich auf <code>Delay = 14 + 7 = 21 ticks</code>. Der nachfolgende Abstand zwischen Next und NextNext bleibt nominal bei <code>Delay = 18 ticks</code>, sodass sich der absolute Zeitpunkt von NextNext ebenfalls verschiebt.\n</li><li>Szenario „Maximum Advance“: Der Ablaufpunkt <code>Next</code> wird um seinen maximalen Vorziehwert (<code>MaxAdvance = 2 ticks</code>) verkürzt. Die Verzögerung zwischen Current und Next verkürzt sich auf <code>Delay = 14 - 2 = 12 ticks</code> (im Schaubild als Korrektur/Anpassung <code>Delay = 14 +/- 2 = 16 / 12 ticks</code> adressiert). Der anschließende Abstand zu NextNext bleibt mit <code>Delay = 18 ticks</code> unverändert.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht die Randbedingungen für das OS-Modul bei der Synchronisation synchronisierbarer Schedule Tables (AUTOSAR OS SWS). Die Werte <code>OsScheduleTableSyncType</code>, <code>OsScheduleTableMaxRetard</code> und <code>OsScheduleTableMaxAdvance</code> begrenzen den Betrag, um den das Betriebssystem den nächsten Expiry Point verzögern oder vorziehen darf, um Taktabweichungen zur Synchronisationsquelle auszugleichen, ohne die Minimalabstände oder Reihenfolgen von Task-Aktivierungen und Event-Settings zu verletzen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-9ac500cca982aa0c", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Deklarationsansicht aufeinanderfolgender Ablaufzeitpunkte (Expiry Points) einer Schedule Table im AUTOSAR OS Schedule Table Management. Gezeigt wird der obere Kopfbereich einer Konfiguration von drei sequentiellen Expiry Points ohne die zugehörigen Verzögerungsszenarien.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei aufeinanderfolgende Ablaufpunkte (Expiry Points) einer Schedule Table:</p>\n<ul class=\"fig-list\"><li><code>Expiry Point Current</code>: Konfiguriert mit <code>Offset 10 ticks</code>, <code>Task Activations</code>, <code>Event Settings</code>, <code>MaxRetard</code> und <code>MaxAdvance</code>.\n</li><li><code>Expiry Point Next</code> (hervorgehoben): Konfiguriert mit <code>Offset 24 ticks</code>, <code>Task Activations</code>, <code>Event Settings</code>, <code>MaxRetard 7 ticks</code> und <code>MaxAdvance 2 ticks</code>.\n</li><li><code>Expiry Point NextNext</code>: Konfiguriert mit <code>Offset 42 ticks</code>, <code>Task Activations</code>, <code>Event Settings</code>, <code>MaxRetard</code> und <code>MaxAdvance</code>.\n</li><li>Anbindungslinien an eine Zeitachse am unteren Rand (die Zeitbeschriftungen und Szenarien sind abgeschnitten).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Sequenzielle Abfolge dreier Ablaufpunkte <code>Current</code>, <code>Next</code> und <code>NextNext</code> bei den nominellen Offsets 10, 24 und 42 Ticks. Dynamische Anpassungsszenarien sind im sichtbaren Bildbereich nicht dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dokumentiert die Parameterstruktur von Ablaufpunkten innerhalb einer Schedule Table (<code>OsScheduleTableExpiryPoint</code>) mit Nominal-Offsets sowie Konfigurationsfeldern für <code>Task Activations</code>, <code>Event Settings</code>, <code>MaxRetard</code> und <code>MaxAdvance</code>. Dient als Referenz für die Konfiguration synchronisierbarer Schedule Tables.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-58931bcfaa1a5ada", "to": "FIG-dd6fe293799ef612", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-dd6fe293799ef612", "to": "FIG-9ac500cca982aa0c", "fr": "R3.2.3", "tr": "R4.0.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Diagramminhalt beschnitten bzw. unvollständig gerendert: Die Abschnitte „Expected Delays“, „Maximum Retardation“ und „Maximum Advance“ sowie die Beschriftungen der Zeitachsen/Verzögerungen („Delay = 14“, „Delay = 18“ etc.) sind am unteren Bildrand abgeschnitten.\n</li><li>Vektorgrafik-Neuzeichnung der verbleibenden oberen Boxen („Expiry Point Current“, „Expiry Point Next“, „Expiry Point NextNext“) mit höherer typografischer Auflösung und korrigierter Textausrichtung.\n</li></ul>"}]};
